import * as DataStore from "@api/DataStore";
import definePlugin, { PluginNative } from "@utils/types";

// Plain JS core shared with the userscript, extension and BetterDiscord builds (generated by build.ps1)
// @ts-ignore
import E2EEDiscord from "./core.js";

interface E2EEInstance {
    start(): void;
    stop(): void;
}

// Desktop only: downloads attachments outside the page, where Discord's CDN CORS rules don't apply
const Native = (VencordNative as any)?.pluginHelpers?.E2EEDiscord as PluginNative<typeof import("./native")> | undefined;

let instance: E2EEInstance | null = null;

export default definePlugin({
    name: "E2EEDiscord",
    description: "End-to-end encryption for messages and files, with automatic key exchange. Right-click the lock in the chat bar for the menu. Made by XO.ST",
    authors: [{ name: "XO.ST", id: 0n }],

    start() {
        instance ??= E2EEDiscord({
            name: "vencord",
            window,
            storage: {
                get: async (key: string) => (await DataStore.get(key)) ?? null,
                set: (key: string, value: unknown) => DataStore.set(key, value)
            },
            fetchBinary: Native?.fetchBinary ? (url: string) => Native.fetchBinary(url) : undefined
        }) as E2EEInstance;
        instance.start();
    },

    stop() {
        instance?.stop();
    }
});
